/* eslint-disable consistent-return */
import React, { useMemo } from 'react';
import { XCircle } from '@hexa-ui/icons';
import { AlertProps } from './Alert.types';
import {
  AlertContainer,
  MessageText,
  ActionsButtons,
  ActionButton,
  ContentContainer,
  InfoIcon,
  WarningIcon,
  ErrorIcon,
  SuccessIcon,
  OnlyActionContainer,
  IconContainer,
  CloseButton,
  GeneralContainer,
} from './Alert.styles';

export default function Alert({
  type = 'info',
  componentVariant = 'alert',
  message,
  actions,
  showCloseButton,
  onClose,
  ...rest
}: AlertProps): JSX.Element {
  const onlyAction = actions && actions.length === 1 ? actions[0] : null;
  const hasMultipleActions = actions && actions.length >= 2;
  const Icon = useMemo(() => {
    if (componentVariant === 'snackbar') {
      return null;
    }

    if (type === 'info') {
      return <InfoIcon size="large" />;
    }

    if (type === 'success') {
      return <SuccessIcon size="large" />;
    }

    if (type === 'warning') {
      return <WarningIcon size="large" />;
    }

    if (type === 'error') {
      return <ErrorIcon size="large" />;
    }
  }, [type, componentVariant]);
  return (
    <AlertContainer type={type} componentVariant={componentVariant} {...rest}>
      <GeneralContainer>
        {!hasMultipleActions ? <IconContainer>{Icon}</IconContainer> : Icon}
        <ContentContainer>
          <MessageText
            componentVariant={componentVariant}
            buttonVariant={onlyAction?.name ? 'withButtonAction' : 'withoutButtonAction'}
          >
            {message}
          </MessageText>
          {onlyAction ? (
            <OnlyActionContainer>
              <ActionButton key={onlyAction.name} type="button" onClick={onlyAction.action}>
                {onlyAction.name}
              </ActionButton>
            </OnlyActionContainer>
          ) : null}
        </ContentContainer>
        {showCloseButton && onClose ? (
          <CloseButton icon={XCircle} variant="inherit" size="small" onClick={() => onClose()} />
        ) : null}
      </GeneralContainer>
      {hasMultipleActions ? (
        <ActionsButtons>
          {actions.map((action) => (
            <ActionButton key={action?.name} type="button" onClick={action?.action}>
              {action?.name}
            </ActionButton>
          ))}
        </ActionsButtons>
      ) : null}
    </AlertContainer>
  );
}
